// Shared canonical treasury quotes; separate personal and officer settlement paths.
let allianceTreasuryQuote=null,allianceTreasuryRequest=null,allianceTreasuryBusy=false,allianceTreasuryQuoteAt=0;
function allianceTreasuryRows(mode){const personal=mode==='personal',prefix=personal?'spaceport-alliance':'officer-bank';return '<div class="resource-transfer-list">'+Object.entries(RES).map(([from,res],i)=>'<section class="resource-transfer-row"><h3 class="resource-transfer-type"><i class="resource-transfer-icon" data-resource="'+from+'" aria-hidden="true"></i>'+esc(res.label)+'</h3><div class="resource-transfer-stock"><small>'+(personal?'My planet / Fund':'Alliance Fund')+'</small><b data-treasury-stock="'+from+'">—</b></div><div class="field"><label for="'+prefix+'-'+from+'-to">Receive</label><select id="'+prefix+'-'+from+'-to" data-treasury-draft data-alliance-fund-draft>'+Object.entries(RES).filter(([id])=>id!==from).map(([id,r],j)=>'<option value="'+id+'" '+(j===i%2?'selected':'')+'>'+esc(r.label)+'</option>').join('')+'</select></div><div class="field"><label for="'+prefix+'-'+from+'-amount">Offer</label><input id="'+prefix+'-'+from+'-amount" data-treasury-draft data-alliance-fund-draft type="number" min="1" step="1" value="1000"></div><p class="resource-transfer-result" data-treasury-preview="'+from+'">Connecting…</p><button class="btn primary" data-treasury-trade="'+from+'" disabled>EXCHANGE</button></section>').join('')+'</div>';}
function allianceTreasuryMember(){return state.alliance?.name&&state.alliance.name!=='Unaffiliated'&&isAllianceMember('A. Commander');}
function ensureAllianceTreasuryMounted(){
 const port=document.getElementById('galaxyFundContent');let module=document.getElementById('spaceportAllianceFund');
 if(port&&!module){module=document.createElement('section');module.id='spaceportAllianceFund';module.className='panel alliance-treasury-trade';module.dataset.treasuryMode='personal';port.append(module);}
 if(module){const key=allianceTreasuryMember()?(state.alliance.registryId||state.alliance.name):'';if(module.dataset.allianceKey!==key||!module.dataset.initialized){module.dataset.initialized='1';module.dataset.allianceKey=key;module.innerHTML='<div class="ph"><div class="pt">ALLIANCE FUND</div><span class="meta">PERSONAL RESOURCE EXCHANGE</span></div>'+(key?'<p class="fund-copy">Trade your own resources with your alliance’s finite reserves · 2.5% fee to the Universal Bank, rounded up.</p>'+allianceTreasuryRows('personal')+'<p class="treasury-status" role="status">Connecting…</p>':'<div class="settings-body"><p>Join or create an alliance before using its fund.</p><button class="btn" data-goto="alliance">OPEN ALLIANCE REGISTRATION</button></div>');}}
 const officer=document.getElementById('allianceBankExchange');if(officer&&!officer.dataset.initialized){officer.dataset.initialized='1';officer.dataset.treasuryMode='officer';officer.classList.add('alliance-treasury-trade');officer.innerHTML='<p>Exchange alliance reserves with the Universal Bank. Personal resources are unaffected. Owner, HC or Officer access is required.</p>'+allianceTreasuryRows('officer')+'<p class="treasury-status" role="status">Connecting…</p>';}
 if(allianceTreasuryQuote)updateAllianceTreasuryQuotes();
 if((module&&allianceTreasuryMember()||officer)&&!allianceTreasuryRequest&&Date.now()-allianceTreasuryQuoteAt>30000)void loadAllianceTreasuryQuote();
}
async function loadAllianceTreasuryQuote(){if(allianceTreasuryRequest)return allianceTreasuryRequest;const owner=state;allianceTreasuryRequest=(async()=>{try{const data=await centralDirectoryRequest('/api/spacing-bank');if(state!==owner)return;allianceTreasuryQuote=data;allianceTreasuryQuoteAt=Date.now();if(data.alliance&&data.alliance.name===state.alliance.name){state.alliance.fund={...data.alliance.fund};if(data.alliance.fundSettlementVersion)state.alliance.fundSettlementVersion=data.alliance.fundSettlementVersion;}for(const root of document.querySelectorAll('[data-treasury-mode]'))delete root.dataset.treasuryError;updateAllianceTreasuryQuotes();return data;}catch(error){for(const root of document.querySelectorAll('[data-treasury-mode]')){root.dataset.treasuryError=error.message;const box=root.querySelector('.treasury-status');if(box)box.textContent=error.message;}return null;}finally{allianceTreasuryRequest=null;}})();return allianceTreasuryRequest;}
function updateAllianceTreasuryQuotes(){const q=allianceTreasuryQuote;for(const root of document.querySelectorAll('[data-treasury-mode]')){const personal=root.dataset.treasuryMode==='personal',alliance=q?.alliance,allowed=!!alliance&&(personal?alliance.canPersonalTrade:alliance.canTrade);for(const row of root.querySelectorAll('.resource-transfer-row')){const button=row.querySelector('[data-treasury-trade]'),from=button.dataset.treasuryTrade,to=row.querySelector('select').value,n=Number(row.querySelector('input').value),gross=personal?n:Math.floor(n*(q?.settings?.values?.[from]||1)/(q?.settings?.values?.[to]||1)),fee=personal?Math.ceil(gross*.025):Math.floor(gross*(q?.settings?.tax??5)/100);row.querySelector('[data-treasury-stock]').textContent=(personal?nfmt(state.resources[from]||0)+' / ':'')+nfmt(alliance?.fund?.[from]||0);row.querySelector('[data-treasury-preview]').textContent=Number.isSafeInteger(n)&&n>0?'Receive '+nfmt(Math.max(0,gross-fee))+' '+RES[to].label+' · Fee '+nfmt(fee)+' ('+(personal?'2.5':q?.settings?.tax??5)+'%)':'Enter a positive whole amount.';button.disabled=allianceTreasuryBusy||!allowed;}const status=root.querySelector('.treasury-status');if(status&&!allianceTreasuryBusy)status.textContent=root.dataset.treasuryError||(!alliance?'No current alliance membership.':!allowed?'Your alliance rank cannot use this exchange.':'Canonical reserves loaded · each exchange is checked at settlement.');}}
async function submitAllianceTreasuryTrade(button){if(allianceTreasuryBusy)return;const root=button.closest('[data-treasury-mode]'),personal=root?.dataset.treasuryMode==='personal',row=button.closest('.resource-transfer-row'),from=button.dataset.treasuryTrade,to=row.querySelector('select').value,amount=Number(row.querySelector('input').value);let q=allianceTreasuryQuote;if(!q?.alliance||!(personal?q.alliance.canPersonalTrade:q.alliance.canTrade)||!Number.isSafeInteger(amount)||amount<1)return notify('Choose a valid exchange permitted by your rank.',true);allianceTreasuryBusy=true;updateAllianceTreasuryQuotes();const owner=state,context={user:state.centralPlayerId,generation:q.generation,alliance:q.alliance.id},status=root.querySelector('.treasury-status');delete root.dataset.treasuryError;try{if(personal&&typeof syncOwnedColony==='function'&&!await syncOwnedColony(true))throw Error(typeof colonySyncLastError==='string'&&colonySyncLastError?colonySyncLastError:'Your colony is still connecting. Please retry shortly.');q=await loadAllianceTreasuryQuote();if(!q)throw Error('Could not refresh treasury quote. No exchange was sent. Retry the connection.');if(state!==owner||state.centralPlayerId!==context.user||q.generation!==context.generation||q.alliance?.id!==context.alliance)throw Error('Alliance membership changed. Refresh before exchanging.');const signature=[state.centralPlayerId,q.generation,q.alliance.id,personal?'personal':'officer',from,to,amount].join('|');let pending=state.pendingAllianceTreasuryTrade;if(!pending||pending.signature!==signature)pending=state.pendingAllianceTreasuryTrade={signature,id:crypto.randomUUID()};save();const data=await centralDirectoryRequest('/api/spacing-bank',{action:personal?'personalAllianceTrade':'allianceTrade',generation:q.generation,revision:q.revision,directoryRevision:q.directoryRevision,id:pending.id,from,to,amount});if(state!==owner)return;recordOrderConfirmation(personal?'personal-alliance-trade':'alliance-bank-trade',{id:pending.id,...data.trade});state.pendingAllianceTreasuryTrade=null;if(data.allianceFund)state.alliance.fund={...data.allianceFund};state.alliance.fundSettlementVersion=1;save();if(typeof refreshAfterCentralWrite==='function')await refreshAfterCentralWrite();await loadAllianceTreasuryQuote();update();}catch(error){root.dataset.treasuryError=error.message;status.textContent=error.message;notify(error.message,true);}finally{allianceTreasuryBusy=false;updateAllianceTreasuryQuotes();}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-treasury-trade]');if(button)void submitAllianceTreasuryTrade(button);});for(const type of ['input','change'])document.addEventListener(type,event=>{if(event.target.matches('[data-treasury-draft]'))updateAllianceTreasuryQuotes();});
